package com.fream.back.domain.style.service.command;

import com.fream.back.domain.faq.entity.FaqBid;
import com.fream.back.domain.faq.service.query.FaqBidQueryService;
import com.fream.back.domain.user.entity.UserSize;
import com.fream.back.domain.user.service.productSize.UserSizeQueryService;
import com.fream.back.domain.style.entity.BidStatus;
import com.fream.back.domain.style.entity.Style;
import com.fream.back.domain.style.entity.StyleBid;
import com.fream.back.domain.style.repository.StyleBidRepository;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.service.query.ProductQueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class StyleBidCommandService {

    private final StyleBidRepository saleBidRepository;
    private final ProductQueryService userQueryService;
    private final UserSizeQueryService productSizeQueryService;
    private final StyleCommandService saleCommandService;
    private final FaqBidQueryService orderBidQueryService;
    @Transactional
    public StyleBid createSaleBid(String sellerEmail, Long productSizeId, int bidPrice,
                                 String returnAddress, String postalCode, String receiverPhone
                                , boolean isWarehouseStorage) {

        Product seller = userQueryService.findByEmail(sellerEmail);


        UserSize productSize = productSizeQueryService.findById(productSizeId)
                .orElseThrow(() -> new IllegalArgumentException("해당 상품 사이즈를 찾을 수 없습니다: " + productSizeId));


        Style sale = saleCommandService.createSale(seller, productSize, returnAddress, postalCode, receiverPhone,isWarehouseStorage);


        StyleBid saleBid = StyleBid.builder()
                .seller(seller)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(BidStatus.PENDING)
                .sale(sale)
                .build();


        saleBid = saleBidRepository.save(saleBid);


        sale.assignSaleBid(saleBid);


        return saleBid;
    }
    @Transactional
    public Long createInstantSaleBid(Long orderBidId,
                                        String sellerEmail,
                                        String returnAddress,
                                        String postalCode,
                                        String receiverPhone) {

        Style sale=saleCommandService.createInstantSale(orderBidId,sellerEmail,returnAddress,postalCode,receiverPhone);

        FaqBid orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));



        StyleBid saleBid = StyleBid.builder()
                .seller(sale.getSeller())
                .productSize(sale.getProductSize())
                .bidPrice(orderBid.getBidPrice())
                .status(BidStatus.MATCHED)
                .sale(sale)
                .order(orderBid.getOrder())
                .build();


        saleBid.assignSale(sale);
        saleBid.assignOrder(orderBid.getOrder());
        sale.assignSaleBid(saleBid);


        saleBidRepository.save(saleBid);


        return sale.getId();
    }

    @Transactional
    public void deleteSaleBid(Long saleBidId) {

        StyleBid saleBid = saleBidRepository.findById(saleBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 SaleBid를 찾을 수 없습니다: " + saleBidId));


        if (saleBid.getOrder() != null) {
            throw new IllegalStateException("SaleBid는 Order와 연결되어 있으므로 삭제할 수 없습니다.");
        }


        if (saleBid.getSale() != null) {
            saleCommandService.deleteSale(saleBid.getSale().getId());
        }


        saleBidRepository.delete(saleBid);
    }
}
package com.fream.back.domain.style.service.command;

import com.fream.back.domain.payment.entity.PaymentCategory;
import com.fream.back.domain.payment.entity.PaymentType;
import com.fream.back.domain.payment.service.command.PaymentCommandService;
import com.fream.back.domain.faq.entity.BidStatus;
import com.fream.back.domain.faq.entity.FaqBid;
import com.fream.back.domain.faq.service.query.FaqBidQueryService;
import com.fream.back.domain.user.entity.UserSize;
import com.fream.back.domain.style.entity.Style;
import com.fream.back.domain.style.entity.StyleBankAccount;
import com.fream.back.domain.style.entity.StyleStatus;
import com.fream.back.domain.style.repository.StyleRepository;
import com.fream.back.domain.address.entity.SellerAddress;
import com.fream.back.domain.address.service.command.SellerAddressCommandService;
import com.fream.back.domain.product.dto.BankAccount.BankAccountInfoDto;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.service.bankaccount.BankAccountQueryService;
import com.fream.back.domain.product.service.query.ProductQueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class StyleCommandService {

    private final StyleRepository saleRepository;
    private final FaqBidQueryService orderBidQueryService;
    private final PaymentCommandService notificationCommandService;
    private final ProductQueryService userQueryService;
    private final SellerAddressCommandService sellerShipmentCommandService;
    private final BankAccountQueryService bankAccountQueryService;
    private final StyleBankAccountCommandService saleBankAccountCommandService;


    @Transactional
    public Style createInstantSale(
            Long orderBidId,
            String sellerEmail,
            String returnAddress,
            String postalCode,
            String receiverPhone
    ) {

        FaqBid orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));


        Product seller = userQueryService.findByEmail(sellerEmail);


        UserSize productSize = orderBid.getProductSize();


        Style sale = Style.builder()
                .seller(seller)
                .productSize(productSize)
                .returnAddress(returnAddress)
                .postalCode(postalCode)
                .receiverPhone(receiverPhone)
                .status(StyleStatus.PENDING_SHIPMENT)
                .build();

        Style savedSale = saleRepository.save(sale);



        BankAccountInfoDto bankAccountInfo = bankAccountQueryService.getBankAccount(seller.getEmail());
        StyleBankAccount saleBankAccount = saleBankAccountCommandService.createSaleBankAccount(
                bankAccountInfo.getBankName(),
                bankAccountInfo.getAccountNumber(),
                bankAccountInfo.getAccountHolder(),
                savedSale
        );
        savedSale.assignSaleBankAccount(saleBankAccount);


        orderBid.assignSale(savedSale);
        orderBid.updateStatus(BidStatus.MATCHED);


        Product buyer = orderBid.getUser();
        notificationCommandService.createNotification(
                buyer.getId(),
                PaymentCategory.SHOPPING,
                PaymentType.BID,
                "구매 입찰에 판매자가 등록되었습니다. 확인해보세요!"
        );

        return savedSale;
    }

    @Transactional
    public Style createSale(Product seller, UserSize productSize, String returnAddress,
                           String postalCode, String receiverPhone, boolean isWarehouseStorage) {

        BankAccountInfoDto bankAccountInfo = bankAccountQueryService.getBankAccount(seller.getEmail());


        Style sale = Style.builder()
                .seller(seller)
                .productSize(productSize)
                .returnAddress(returnAddress)
                .postalCode(postalCode)
                .receiverPhone(receiverPhone)
                .isWarehouseStorage(isWarehouseStorage)
                .status(StyleStatus.PENDING_SHIPMENT)
                .build();

        Style savedSale = saleRepository.save(sale);


        StyleBankAccount saleBankAccount = saleBankAccountCommandService.createSaleBankAccount(
                bankAccountInfo.getBankName(),
                bankAccountInfo.getAccountNumber(),
                bankAccountInfo.getAccountHolder(),
                savedSale
        );


        savedSale.assignSaleBankAccount(saleBankAccount);


        notificationCommandService.createNotification(
                seller.getId(),
                PaymentCategory.SHOPPING,
                PaymentType.BID,
                "판매 입찰이 등록되었습니다."
        );

        return savedSale;
    }


    @Transactional
    public SellerAddress createSellerShipment(Long saleId, String courier, String trackingNumber) {

        SellerAddress shipment = sellerShipmentCommandService.createSellerShipment(saleId, courier, trackingNumber);


        updateSaleStatus(saleId, StyleStatus.IN_TRANSIT);

        return shipment;
    }

    @Transactional
    public void updateSaleStatus(Long saleId, StyleStatus newStatus) {
        Style sale = saleRepository.findById(saleId)
                .orElseThrow(() -> new IllegalArgumentException("해당 Sale을 찾을 수 없습니다: " + saleId));


        System.out.println("현재 상태: " + sale.getStatus());
        System.out.println("전환하려는 상태: " + newStatus);
        if (!sale.getStatus().canTransitionTo(newStatus)) {
            throw new IllegalStateException("Style 상태를 " + newStatus + "로 전환할 수 없습니다.");
        }

        sale.updateStatus(newStatus);
    }

    @Transactional
    public void deleteSale(Long saleId) {

        Style sale = saleRepository.findById(saleId)
                .orElseThrow(() -> new IllegalArgumentException("해당 Sale을 찾을 수 없습니다: " + saleId));


        saleRepository.delete(sale);
    }


}


