@Service
@RequiredArgsConstructor
public class StyleCommandService {

    private final StyleRepository saleRepository;
    private final FaqBidQueryService orderBidQueryService;
    private final PaymentCommandService notificationCommandService;
    private final ProductQueryService userQueryService;
    private final SellerAddressCommandService sellerShipmentCommandService;
    private final BankAccountQueryService bankAccountQueryService;
    private final StyleBankAccountCommandService saleBankAccountCommandService;


    @Transactional
    public Style createInstantSale(
            Long orderBidId,
            String sellerEmail,
            String returnAddress,
            String postalCode,
            String receiverPhone
    ) {

        FaqBid orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));


        Product seller = userQueryService.findByEmail(sellerEmail);


        UserSize productSize = orderBid.getProductSize();


        Style sale = Style.builder()
                .seller(seller)
                .productSize(productSize)
                .returnAddress(returnAddress)
                .postalCode(postalCode)
                .receiverPhone(receiverPhone)
                .status(StyleStatus.PENDING_SHIPMENT)
                .build();

        Style savedSale = saleRepository.save(sale);



        BankAccountInfoDto bankAccountInfo = bankAccountQueryService.getBankAccount(seller.getEmail());
        StyleBankAccount saleBankAccount = saleBankAccountCommandService.createSaleBankAccount(
                bankAccountInfo.getBankName(),
                bankAccountInfo.getAccountNumber(),
                bankAccountInfo.getAccountHolder(),
                savedSale
        );
        savedSale.assignSaleBankAccount(saleBankAccount);


        orderBid.assignSale(savedSale);
        orderBid.updateStatus(BidStatus.MATCHED);


        Product buyer = orderBid.getUser();
        notificationCommandService.createNotification(
                buyer.getId(),
                PaymentCategory.SHOPPING,
                PaymentType.BID,
                "구매 입찰에 판매자가 등록되었습니다. 확인해보세요!"
        );

        return savedSale;
    }

    @Transactional
    public Style createSale(Product seller, UserSize productSize, String returnAddress,
                           String postalCode, String receiverPhone, boolean isWarehouseStorage) {

        BankAccountInfoDto bankAccountInfo = bankAccountQueryService.getBankAccount(seller.getEmail());


        Style sale = Style.builder()
                .seller(seller)
                .productSize(productSize)
                .returnAddress(returnAddress)
                .postalCode(postalCode)
                .receiverPhone(receiverPhone)
                .isWarehouseStorage(isWarehouseStorage)
                .status(StyleStatus.PENDING_SHIPMENT)
                .build();

        Style savedSale = saleRepository.save(sale);


        StyleBankAccount saleBankAccount = saleBankAccountCommandService.createSaleBankAccount(
                bankAccountInfo.getBankName(),
                bankAccountInfo.getAccountNumber(),
                bankAccountInfo.getAccountHolder(),
                savedSale
        );


        savedSale.assignSaleBankAccount(saleBankAccount);


        notificationCommandService.createNotification(
                seller.getId(),
                PaymentCategory.SHOPPING,
                PaymentType.BID,
                "판매 입찰이 등록되었습니다."
        );

        return savedSale;
    }


    @Transactional
    public SellerAddress createSellerShipment(Long saleId, String courier, String trackingNumber) {

        SellerAddress shipment = sellerShipmentCommandService.createSellerShipment(saleId, courier, trackingNumber);


        updateSaleStatus(saleId, StyleStatus.IN_TRANSIT);

        return shipment;
    }

    @Transactional
    public void updateSaleStatus(Long saleId, StyleStatus newStatus) {
        Style sale = saleRepository.findById(saleId)
                .orElseThrow(() -> new IllegalArgumentException("해당 Sale을 찾을 수 없습니다: " + saleId));


        System.out.println("현재 상태: " + sale.getStatus());
        System.out.println("전환하려는 상태: " + newStatus);
        if (!sale.getStatus().canTransitionTo(newStatus)) {
            throw new IllegalStateException("Style 상태를 " + newStatus + "로 전환할 수 없습니다.");
        }

        sale.updateStatus(newStatus);
    }

    @Transactional
    public void deleteSale(Long saleId) {

        Style sale = saleRepository.findById(saleId)
                .orElseThrow(() -> new IllegalArgumentException("해당 Sale을 찾을 수 없습니다: " + saleId));


        saleRepository.delete(sale);
    }


}


